/**
 * {@link LmdbValueLookupOptimizer} replaces every constant in the query with its LMDB wrapper. Two query nodes that
 * hold the <em>same</em> {@link Value} instance must keep holding one instance afterwards: {@code ConstantOptimizer}
 * folds every {@code NOW()} of a query into one shared literal, and the SPARQL test suite (SES869) asserts that
 * {@code SELECT ?p (NOW() AS ?n) { BIND(NOW() AS ?p) }} yields {@code p == n}. A fresh wrapper per node breaks that
 * identity on LMDB only.
 */
public class LmdbValueLookupIdentityTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void sharedValueInstanceResolvesToOneLmdbValueAcrossConstantsAndVars(@TempDir File dataDir) throws Exception {
		ValueStore valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig());
		try {
			Literal shared = VF.createLiteral("shared-instance");
			ValueConstant first = new ValueConstant(shared);
			ValueConstant second = new ValueConstant(shared);
			Var var = Var.of("fixed", shared);
			StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
			Filter query = new Filter(new Join(pattern, new StatementPattern(Var.of("s"), Var.of("q"), var)),
					new Compare(new Compare(Var.of("o"), first, Compare.CompareOp.EQ), second,
							Compare.CompareOp.EQ));

			new LmdbValueLookupOptimizer(valueStore).optimize(query, null, EmptyBindingSet.getInstance());

			Value firstValue = first.getValue();
			assertInstanceOf(LmdbValue.class, firstValue);
			assertSame(firstValue, second.getValue(), "equal constants of one query must share one LMDB wrapper");
			Var resolvedVar = ((StatementPattern) ((Join) query.getArg()).getRightArg()).getObjectVar();
			assertInstanceOf(LmdbValueVar.class, resolvedVar);
			assertSame(firstValue, resolvedVar.getValue(), "a Var holding the same instance must share the wrapper");
			assertEquals(shared, firstValue);
		} finally {
			valueStore.close();
		}
	}

	@Test
	void distinctButEqualInstancesStillResolveToEqualValues(@TempDir File dataDir) throws Exception {
		ValueStore valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig());
		try {
			ValueConstant first = new ValueConstant(VF.createLiteral("equal"));
			ValueConstant second = new ValueConstant(VF.createLiteral("equal"));
			Filter query = new Filter(new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")),
					new Compare(new Compare(Var.of("o"), first, Compare.CompareOp.EQ), second,
							Compare.CompareOp.EQ));

			new LmdbValueLookupOptimizer(valueStore).optimize(query, null, EmptyBindingSet.getInstance());

			assertInstanceOf(LmdbValue.class, first.getValue());
			assertInstanceOf(LmdbValue.class, second.getValue());
			assertEquals(first.getValue(), second.getValue());
		} finally {
			valueStore.close();
		}
	}

	@Test
	void storedLiteralStillResolvesToKnownValue(@TempDir File dataDir) throws Exception {
		ValueStore valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig());
		try {
			Literal stored = VF.createLiteral("stored-literal");
			valueStore.startTransaction(true);
			long storedId = valueStore.storeValue(stored);
			valueStore.commit();
			assertNotEquals(LmdbValue.UNKNOWN_ID, storedId);

			Literal missing = VF.createLiteral("missing-literal");
			ValueConstant storedConstant = new ValueConstant(stored);
			Var storedVar = Var.of("stored", stored);
			Var missingVar = Var.of("missing", missing);
			Filter query = new Filter(new StatementPattern(Var.of("s"), storedVar, missingVar),
					new Compare(Var.of("s"), storedConstant, Compare.CompareOp.NE));

			new LmdbValueLookupOptimizer(valueStore).optimize(query, null, EmptyBindingSet.getInstance());

			LmdbValue constantValue = assertInstanceOf(LmdbValue.class, storedConstant.getValue());
			assertEquals(storedId, constantValue.getInternalID());
			LmdbValueVar resolvedStored = assertInstanceOf(LmdbValueVar.class,
					((StatementPattern) query.getArg()).getPredicateVar());
			assertTrue(resolvedStored.isLmdbValueResolved());
			assertNotNull(resolvedStored.getLmdbValue(), "a literal present in the store resolves to a known value");
			assertSame(constantValue, resolvedStored.getValue());
			LmdbValueVar resolvedMissing = assertInstanceOf(LmdbValueVar.class,
					((StatementPattern) query.getArg()).getObjectVar());
			assertTrue(resolvedMissing.isLmdbValueResolved());
			assertEquals(null, resolvedMissing.getLmdbValue(), "a literal absent from the store has no known value");
		} finally {
			valueStore.close();
		}
	}

	@Test
	void nowSharedLiteralKeepsIdentityOnLmdbStore(@TempDir File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			try (TupleQueryResult result = conn
					.prepareTupleQuery("SELECT ?p ( NOW() as ?n ) { BIND (NOW() as ?p ) }")
					.evaluate()) {
				assertTrue(result.hasNext());
				BindingSet bs = result.next();
				Value p = bs.getValue("p");
				Value n = bs.getValue("n");
				assertNotNull(p);
				assertNotNull(n);
				assertEquals(p, n);
				assertSame(p, n, "both NOW() of one query must resolve to the same shared literal instance");
			}
		} finally {
			repository.shutDown();
		}
	}

	/**
	 * Re-executing a {@code NOW()} query must observe the current clock: the folded {@code NOW()} constant of the first
	 * execution must not be served again from a cached plan.
	 */
	@Test
	void nowIsReevaluatedOnRepeatedExecution(@TempDir File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			String query = "SELECT ?p ( NOW() as ?n ) { BIND (NOW() as ?p ) }";
			Literal first = evaluateNow(conn, query);
			long start = System.currentTimeMillis();
			while (System.currentTimeMillis() == start) {
				Thread.onSpinWait();
			}
			Literal second = evaluateNow(conn, query);
			Literal third = evaluateNow(conn, query);
			assertNotEquals(first, second, "second execution must not reuse the first execution's NOW() value");
			assertTrue(second.calendarValue().compare(first.calendarValue()) > 0, first + " < " + second);
			assertTrue(third.calendarValue().compare(second.calendarValue()) >= 0, second + " <= " + third);
		} finally {
			repository.shutDown();
		}
	}

	private static Literal evaluateNow(SailRepositoryConnection conn, String query) {
		try (TupleQueryResult result = conn.prepareTupleQuery(query).evaluate()) {
			assertTrue(result.hasNext());
			BindingSet bs = result.next();
			Value n = bs.getValue("n");
			assertSame(bs.getValue("p"), n);
			return assertInstanceOf(Literal.class, n);
		}
	}
}
